/* source: https://exclusivaviagens.com.br/wp-content/plugins/wordpress-whatsapp-support/assets/css/wws-public-style.css?ver=2.0.7 */
.wws-clearfix { clear: both; }
.wws-shadow { box-shadow: rgba(0, 0, 0, 0.1) 0px 0px 50px; }
.wws-gradient { z-index: -1; position: fixed; width: 500px; height: 500px; content: ""; pointer-events: none; display: none; }
@keyframes wws-shake { 
  0% { transform: translateX(0px); }
  25% { transform: translateX(-8px); }
  50% { transform: translateX(8px); }
  100% { transform: translateX(0px); }
}
.wws-shake-animation { animation: 300ms ease 0s 1 normal none running wws-shake; }
.wws-popup .wws-gdpr { border-top: 1px dashed rgb(238, 238, 238); padding: 8px 12px 6px; background: rgb(255, 255, 255); font-size: 12px; color: rgb(136, 143, 187); user-select: none; outline: none !important; }
.wws-popup .wws-gdpr label { color: rgb(136, 143, 187); display: block; font-weight: normal; margin: 0px; padding: 0px; font-size: 12px; }
.wws-popup .wws-gdpr label input[type="checkbox"] { vertical-align: middle; margin-right: 4px; padding: 0px; }
.wws-shortcode-btn { padding: 4px 10px; margin: 2px; border-radius: 3px; text-align: center; vertical-align: middle; justify-content: center; align-items: center; text-decoration: none !important; }
.wws-shortcode-btn:hover { box-shadow: rgba(0, 0, 0, 0.16) 0px 3px 8px; }
.wws-shortcode-btn > svg { vertical-align: middle; margin-right: 5px; width: 16px; height: 16px; }
.wws-spinner { margin: 80px auto; width: 70px; text-align: center; }
.wws-spinner > div { width: 18px; height: 18px; border-radius: 100%; display: inline-block; animation: 1.4s ease-in-out 0s infinite normal both running wws-sk-bouncedelay; }
.wws-spinner .wws-bounce1 { animation-delay: -0.32s; }
.wws-spinner .wws-bounce2 { animation-delay: -0.16s; }
@keyframes wws-sk-bouncedelay { 
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1); }
}
.wws-qr { width: auto; max-width: 98%; padding: 10px; text-align: center; }
.wws-qr img { display: inline-block !important; }
.wws-popup__open-btn > svg, .wws-popup__open-btn > span { vertical-align: middle; }
.wws-popup__open-btn > svg { padding-right: 2px; width: 16px; height: 16px; }


/* source: inline */
.wws--bg-color { background-color: rgb(34, 193, 94); }
.wws--text-color { color: rgb(255, 255, 255); }
.wws-popup__open-btn { display: flex; justify-content: center; align-items: center; width: 56px; height: 56px; border-radius: 50%; margin-top: 10px; cursor: pointer; }
.wws-popup__open-btn svg { height: auto; width: 30px; }
.wws-popup-container--position { right: 12px; bottom: 12px; }
.wws-popup__open-btn { float: right; }
.wws-gradient--position { bottom: 0px; right: 0px; background: radial-gradient(at right bottom, rgba(29, 39, 54, 0.2) 0px, rgba(29, 39, 54, 0) 72%); }
@media (max-width: 720px) {
  .wws-popup__open-btn { padding: 0px !important; width: 60px !important; height: 60px !important; border-radius: 50% !important; display: flex !important; justify-content: center !important; align-items: center !important; font-size: 30px !important; }
  .wws-popup__open-btn > svg { padding-right: 0px; width: 30px; height: 30px; }
  .wws-popup__open-btn span { display: none; }
}


